#!/usr/bin/env bash
# Question 11: Install an agent with Kustomize. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/kustomize/${Q11_APP}-agent
mkdir -p /opt/course/kustomize/${Q11_APP}-agent
chown -R ubuntu:ubuntu /opt/course
mkdir -p /opt/course/kustomize/${Q11_APP}-agent
cat > /opt/course/kustomize/${Q11_APP}-agent/namespace.yaml <<EOF
apiVersion: v1
kind: Namespace
metadata:
  name: ${Q11_APP}-agents
EOF
cat > /opt/course/kustomize/${Q11_APP}-agent/daemonset.yaml <<EOF
apiVersion: apps/v1
kind: DaemonSet
metadata:
  name: ${Q11_APP}-agent
  namespace: ${Q11_APP}-agents
spec:
  selector:
    matchLabels: { app: ${Q11_APP}-agent }
  template:
    metadata:
      labels: { app: ${Q11_APP}-agent }
    spec:
      containers:
        - name: agent
          image: busybox:1.36
          command: ["sh", "-c", "while true; do date; sleep 60; done"]
          resources:
            requests: { cpu: 5m, memory: 8Mi }
EOF
cat > /opt/course/kustomize/${Q11_APP}-agent/kustomization.yaml <<EOF
apiVersion: kustomize.config.k8s.io/v1beta1
kind: Kustomization
resources:
  - namespace.yaml
  - daemonset.yaml
EOF
chown -R ubuntu:ubuntu /opt/course
sha256sum /opt/course/kustomize/${Q11_APP}-agent/namespace.yaml /opt/course/kustomize/${Q11_APP}-agent/daemonset.yaml > /root/.cka-kustomize-${Q11_APP}-agent.sums
kubectl delete namespace "${Q11_APP}-agents" --ignore-not-found --wait=true >/dev/null
: "${Q11_APP}"
